  "knowledge": "Return on Cost (ROC)",
  "description": "Assesses the fund's one-year performance relative to its cost, indicating how much return is generated per unit of expense.",
  "definition": "ROC = \frac{\text{Fund's 1-year return}}{\text{Net expense ratio}}"
}

{
  "id": 30,
  "knowledge": "Performance-Cost Efficiency Score",
  "description": "Calculates a fund's efficiency by measuring its annual outperformance relative to its cost compared to peers.",
  "definition": "\text{PCES} = \frac{\text{Annual Fund Outperformance}}{\text{Relative Expense Ratio}}"
}

{
  "id": 26,
  "knowledge": "Net Expense Ratio",
  "description": "Illustrates the fund's net annual cost (Expense Ratio).",
  "definition": "The annual fee charged to investors as a percentage of assets. A value of 0.005 corresponds to a 0.5% annual fee. Lower is generally better, as costs directly reduce returns."
}
